 967→
 968→        let mut custom = HashMap::new();
 969→        custom.insert(
 970→            "phantom-tool".to_string(),
 971→            CustomRequirement {
 972→                check: CustomRequirementCheck::CommandSucceeds {
 973→                    command: "false".to_string(),
