  1→//! Requirement status types for gap detection.
  2→//!
  3→//! Each requirement check produces a `RequirementStatus` that describes
  4→//! whether and how a tool or service is available on the system.
  5→
  6→use std::path::PathBuf;
  7→
  8→/// The result of checking a single requirement.
  9→#[derive(Debug, Clone)]
 10→pub enum RequirementStatus {
 11→    /// Tool is present and managed properly (version manager, Homebrew, etc.)
 12→    Satisfied,
 13→
 14→    /// Tool binary exists but comes from a system/default install that's likely
 15→    /// unsuitable (e.g., /usr/bin/ruby on macOS, /usr/bin/python3 on Ubuntu).
 16→    /// The step can proceed but the user should be warned.
 17→    SystemOnly {
 18→        /// Path to the system binary
 19→        path: PathBuf,
 20→        /// Template to install a proper version
 21→        install_template: Option<String>,
 22→        /// Warning message for the user
 23→        warning: String,
 24→    },
 25→
 26→    /// Tool binary exists but comes from a version manager that isn't activated
 27→    /// in this shell context (e.g., nvm-managed Node not on PATH in a non-login shell).
 28→    /// Bivvy can activate it by adding the binary's parent directory to PATH.
 29→    Inactive {
 30→        /// Name of the version manager (e.g., "rbenv", "nvm")
 31→        manager: String,
 32→        /// The resolved binary path from `<manager> which <tool>`.
 33→        binary_path: PathBuf,
 34→        /// Human-readable hint for activation (e.g., 'eval "$(rbenv init -)"')
 35→        activation_hint: String,
 36→    },
 37→
 38→    /// For services: binary is present but the service isn't running or reachable.
 39→    ServiceDown {
 40→        /// Whether the service binary is installed
 41→        binary_present: bool,
 42→        /// Template to install the service
 43→        install_template: Option<String>,
 44→        /// Command to start the service (e.g., "brew services start postgresql@16").
 45→        start_command: Option<String>,
 46→        /// Human-readable hint shown if start_command is None or user declines.
 47→        start_hint: String,
 48→    },
 49→
 50→    /// Tool is genuinely not installed anywhere.
 51→    Missing {
 52→        /// Template to install the tool
 53→        install_template: Option<String>,
 54→        /// Human-readable install instructions
 55→        install_hint: Option<String>,
 56→    },
 57→
 58→    /// Requirement name isn't in the registry. Config error — lint should catch this.
 59→    Unknown,
 60→}
 61→
 62→impl RequirementStatus {
 63→    /// Whether the requirement is satisfied (tool available and ready).
 64→    pub fn is_satisfied(&self) -> bool {
 65→        matches!(self, RequirementStatus::Satisfied)
 66→    }
 67→
 68→    /// Whether the step can proceed (possibly with warnings).
 69→    pub fn can_proceed(&self) -> bool {
 70→        matches!(
 71→            self,
 72→            RequirementStatus::Satisfied | RequirementStatus::SystemOnly { .. }
 73→        )
 74→    }
 75→}
 76→
 77→/// The result of checking a single requirement for a step.
 78→#[derive(Debug, Clone)]
 79→pub struct GapResult {
 80→    /// The requirement name that was checked
 81→    pub requirement: String,
 82→    /// The status of the requirement
 83→    pub status: RequirementStatus,
 84→}
