 14→
 15→/// Status of a step in the workflow.
 16→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 17→pub enum StepStatus {
 18→    /// Step is waiting to run.
 19→    Pending,
 20→
 21→    /// Step is currently executing.
 22→    Running,
 23→
 24→    /// Step completed successfully.
 25→    Completed,
 26→
 27→    /// Step failed.
 28→    Failed,
 29→
 30→    /// Step was skipped (already complete or dependency failed).
 31→    Skipped,
 32→}
 33→
 34→impl StepStatus {
 35→    /// Check if this is a terminal state (no more changes expected).
 36→    pub fn is_terminal(&self) -> bool {
 37→        matches!(
 38→            self,
 39→            StepStatus::Completed | StepStatus::Failed | StepStatus::Skipped
 40→        )
 41→    }
 42→
 43→    /// Get a display character for this status.
 44→    pub fn display_char(&self) -> char {
 45→        match self {
 46→            StepStatus::Pending => '○',
 47→            StepStatus::Running => '◉',
 48→            StepStatus::Completed => '✓',
 49→            StepStatus::Failed => '✗',
 50→            StepStatus::Skipped => '⊘',
 51→        }
 52→    }
 53→}
 54→
 55→impl std::fmt::Display for StepStatus {
 56→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 57→        let s = match self {
 58→            StepStatus::Pending => "pending",
 59→            StepStatus::Running => "running",
 60→            StepStatus::Completed => "completed",
 61→            StepStatus::Failed => "failed",
 62→            StepStatus::Skipped => "skipped",
 63→        };
 64→        write!(f, "{}", s)
 65→    }
 66→}
 67→
 68→/// Result of executing a step.
 69→#[derive(Debug)]
 70→pub struct StepResult {
 71→    /// Step name.
 72→    pub name: String,
 73→
 74→    /// Whether the step succeeded.
 75→    pub success: bool,
 76→
 77→    /// Execution duration.
 78→    pub duration: Duration,
 79→
 80→    /// Exit code (if command was run).
 81→    pub exit_code: Option<i32>,
 82→
 83→    /// Whether step was skipped (already complete).
 84→    pub skipped: bool,
 85→
 86→    /// Completion check result (if run).
 87→    pub check_result: Option<CheckResult>,
 88→
 89→    /// Error message (if failed).
 90→    pub error: Option<String>,
 91→
 92→    /// Captured output (if available).
 93→    pub output: Option<String>,
 94→
 95→    /// Recovery detail (e.g., "succeeded on retry (attempt 2)", "skipped by user").
 96→    pub recovery_detail: Option<String>,
 97→}
 98→
 99→impl StepResult {
100→    /// Create a skipped result.
101→    pub fn skipped(name: &str, check_result: CheckResult) -> Self {
102→        Self {
103→            name: name.to_string(),
104→            success: true,
105→            duration: Duration::ZERO,
106→            exit_code: None,
107→            skipped: true,
108→            check_result: Some(check_result),
109→            error: None,
110→            output: None,
111→            recovery_detail: None,
112→        }
113→    }
114→
115→    /// Create a success result.
116→    pub fn success(
117→        name: &str,
118→        duration: Duration,
119→        exit_code: Option<i32>,
120→        output: Option<String>,
121→    ) -> Self {
122→        Self {
123→            name: name.to_string(),
124→            success: true,
125→            duration,
126→            exit_code,
127→            skipped: false,
128→            check_result: None,
129→            error: None,
130→            output,
131→            recovery_detail: None,
132→        }
133→    }
134→
135→    /// Create a failure result.
136→    pub fn failure(name: &str, duration: Duration, error: String, output: Option<String>) -> Self {
137→        Self {
138→            name: name.to_string(),
139→            success: false,
140→            duration,
141→            exit_code: None,
142→            skipped: false,
143→            check_result: None,
144→            error: Some(error),
145→            output,
146→            recovery_detail: None,
147→        }
148→    }
149→
150→    /// Get the status of this result.
151→    pub fn status(&self) -> StepStatus {
152→        if self.skipped {
153→            StepStatus::Skipped
154→        } else if self.success {
155→            StepStatus::Completed
156→        } else {
157→            StepStatus::Failed
158→        }
159→    }
160→
161→    /// Generate a summary line for display.
162→    pub fn summary_line(&self) -> String {
163→        let status = self.status();
164→        let duration_str = format_duration(self.duration);
165→
166→        match status {
167→            StepStatus::Completed => {
168→                format!("{} {} ({})", status.display_char(), self.name, duration_str)
169→            }
170→            StepStatus::Skipped => {
171→                let reason = self
172→                    .check_result
173→                    .as_ref()
174→                    .map(|c| c.short_description())
175→                    .unwrap_or("already complete");
176→                format!("{} {} ({})", status.display_char(), self.name, reason)
177→            }
178→            StepStatus::Failed => {
179→                let error = self.error.as_deref().unwrap_or("unknown error");
180→                format!("{} {} - {}", status.display_char(), self.name, error)
181→            }
182→            _ => format!("{} {}", status.display_char(), self.name),
183→        }
184→    }
185→}
186→
187→fn format_duration(duration: Duration) -> String {
188→    let secs = duration.as_secs();
189→    let millis = duration.subsec_millis();
190→
191→    if secs == 0 {
192→        format!("{}ms", millis)
193→    } else if secs < 60 {
194→        format!("{}.{}s", secs, millis / 100)
195→    } else {
196→        let mins = secs / 60;
197→        let secs = secs % 60;
198→        format!("{}m {}s", mins, secs)
199→    }
200→}

