 17→
 18→/// Template registry that resolves templates from multiple sources.
 19→#[derive(Debug, Clone)]
 20→pub struct Registry {
 21→    builtin: BuiltinLoader,
 22→    local: LocalLoader,
 23→    remote: RemoteLoader,
 24→}
 25→
 26→impl Registry {
 27→    /// Create a new registry for a project (without remote sources).
 28→    pub fn new(project_root: Option<&Path>) -> Result<Self> {
 29→        Ok(Self {
 30→            builtin: BuiltinLoader::new()?,
 31→            local: LocalLoader::new(project_root)?,
 32→            remote: RemoteLoader::empty(),
 33→        })
 34→    }
 35→
 36→    /// Create a registry with remote template sources.
 37→    pub fn with_remote_sources(
 38→        project_root: Option<&Path>,
 39→        sources: &[TemplateSourceConfig],
 40→    ) -> Result<Self> {
 41→        let fetcher = crate::registry::fetch::HttpFetcher::new();
 42→        let cache_dir = crate::cache::default_cache_dir();
 43→        let cache = crate::cache::CacheStore::new(cache_dir);
 44→
 45→        let remote = RemoteLoader::new(sources, &fetcher, &cache).map_err(|e| {
 46→            BivvyError::ConfigValidationError {
 47→                message: format!("Failed to load remote templates: {}", e),
 48→            }
 49→        })?;
 50→
 51→        Ok(Self {
 52→            builtin: BuiltinLoader::new()?,
 53→            local: LocalLoader::new(project_root)?,
 54→            remote,
 55→        })
 56→    }
 57→
 58→    /// Create a registry with a pre-loaded remote loader (for testing).
 59→    #[cfg(test)]
 60→    pub(crate) fn with_remote_loader(
 61→        project_root: Option<&Path>,
 62→        remote: RemoteLoader,
 63→    ) -> Result<Self> {
 64→        Ok(Self {
 65→            builtin: BuiltinLoader::new()?,
 66→            local: LocalLoader::new(project_root)?,
 67→            remote,
 68→        })
 69→    }
 70→
 71→    /// Resolve a template by name.
 72→    ///
 73→    /// Resolution order (first match wins):
 74→    /// 1. Project-local (.bivvy/templates/)
 75→    /// 2. User-local (~/.bivvy/templates/)
 76→    /// 3. Remote (by priority)
 77→    /// 4. Built-in
 78→    pub fn resolve(&self, name: &str) -> Result<(&Template, TemplateSource)> {
 79→        // Check local first (includes both project and user)
 80→        if let Some((template, source)) = self.local.get_with_source(name) {
 81→            return Ok((template, source));
 82→        }
 83→
 84→        // Check remote sources
 85→        if let Some((template, priority)) = self.remote.get_with_priority(name) {
 86→            return Ok((template, TemplateSource::Remote { priority }));
 87→        }
 88→
 89→        // Check built-in
 90→        if let Some(template) = self.builtin.get(name) {
 91→            return Ok((template, TemplateSource::Builtin));
 92→        }
 93→
 94→        Err(BivvyError::UnknownTemplate {
 95→            name: name.to_string(),
 96→        })
 97→    }
 98→
 99→    /// Get a template by name (without source info).
100→    pub fn get(&self, name: &str) -> Option<&Template> {
101→        self.resolve(name).ok().map(|(t, _)| t)
102→    }
103→
104→    /// Check if a template exists.
105→    pub fn has(&self, name: &str) -> bool {
106→        self.local.has(name) || self.remote.has(name) || self.builtin.get(name).is_some()
107→    }
108→
109→    /// Get all available template names.
110→    pub fn all_template_names(&self) -> Vec<String> {
111→        let mut names: Vec<String> = self
112→            .builtin
113→            .template_names()
114→            .into_iter()
115→            .map(|s| s.to_string())
116→            .collect();
117→
118→        // Add remote templates
119→        for name in self.remote.template_names() {
120→            if !names.contains(&name.to_string()) {
121→                names.push(name.to_string());
122→            }
123→        }
124→
125→        // Add local templates (may override both remote and built-in)
126→        for name in self.local.template_names() {
127→            if !names.contains(&name.to_string()) {
128→                names.push(name.to_string());
129→            }
130→        }
131→
132→        names.sort();
133→        names
134→    }
135→
136→    /// Get templates in detection order for `bivvy init`.
137→    pub fn detection_order(&self) -> Vec<&Template> {
138→        // Start with built-in detection order
139→        self.builtin.detection_order()
140→    }
141→
142→    /// Get the builtin loader (for manifest access).
143→    pub fn builtin(&self) -> &BuiltinLoader {
144→        &self.builtin
145→    }
146→
147→    /// Validate inputs against a template's input contract.
148→    pub fn validate_inputs(
149→        &self,
150→        template_name: &str,

  1→//! HTTP template fetching.
  2→//!
  3→//! Provides an HTTP client for fetching templates from URLs with
  4→//! support for ETag-based conditional requests.
  5→
  6→use anyhow::{bail, Result};
  7→use reqwest::blocking::Client;
  8→use std::time::Duration;
  9→
 10→/// Default maximum response body size (10 MB).
 11→const DEFAULT_MAX_RESPONSE_SIZE: u64 = 10 * 1024 * 1024;
 12→
 13→/// Fetches templates over HTTP/HTTPS.
 14→pub struct HttpFetcher {
 15→    client: Client,
 16→    timeout: Duration,
 17→    max_response_size: u64,
 18→}
 19→
 20→/// Response from fetching a template.
 21→#[derive(Debug)]
 22→pub struct FetchResponse {
 23→    /// The template content.
 24→    pub content: String,
 25→    /// ETag header if present.
 26→    pub etag: Option<String>,
 27→    /// Last-Modified header if present.
 28→    pub last_modified: Option<String>,
 29→}
 30→
 31→impl HttpFetcher {
 32→    /// Create a new HTTP fetcher with default 30-second timeout.
 33→    pub fn new() -> Self {
 34→        Self::with_timeout(Duration::from_secs(30))
 35→    }
 36→
 37→    /// Create a new HTTP fetcher with custom timeout.
 38→    pub fn with_timeout(timeout: Duration) -> Self {
 39→        Self {
 40→            client: Client::builder()
 41→                .user_agent("bivvy")
 42→                .timeout(timeout)
 43→                .build()
 44→                .expect("Failed to build HTTP client"),
 45→            timeout,
 46→            max_response_size: DEFAULT_MAX_RESPONSE_SIZE,
 47→        }
 48→    }
 49→
 50→    /// Create a new HTTP fetcher with custom timeout and max response size.
 51→    #[cfg(test)]
 52→    pub fn with_max_size(timeout: Duration, max_response_size: u64) -> Self {
 53→        Self {
 54→            client: Client::builder()
 55→                .user_agent("bivvy")
 56→                .timeout(timeout)
 57→                .build()
 58→                .expect("Failed to build HTTP client"),
 59→            timeout,
 60→            max_response_size,
 61→        }
 62→    }
 63→
 64→    /// Get the configured timeout.
 65→    pub fn timeout(&self) -> Duration {
 66→        self.timeout
 67→    }
 68→
 69→    /// Fetch a template from a URL.
 70→    pub fn fetch(&self, url: &str) -> Result<FetchResponse> {
 71→        let response = self.client.get(url).send()?;
 72→
 73→        if !response.status().is_success() {
 74→            bail!("HTTP {} fetching {}", response.status(), url);
 75→        }
 76→
 77→        // Check Content-Length if available
 78→        if let Some(len) = response.content_length() {
 79→            if len > self.max_response_size {
 80→                bail!(
 81→                    "Response too large ({} bytes, max {} bytes) from {}",
 82→                    len,
 83→                    self.max_response_size,
 84→                    url
 85→                );
 86→            }
 87→        }
 88→
 89→        let etag = response
 90→            .headers()
 91→            .get("etag")
 92→            .and_then(|v| v.to_str().ok())
 93→            .map(String::from);
 94→
 95→        let last_modified = response
 96→            .headers()
 97→            .get("last-modified")
 98→            .and_then(|v| v.to_str().ok())
 99→            .map(String::from);
100→
101→        let content = response.text()?;
102→
103→        // Also check actual content size (in case Content-Length was missing/wrong)
104→        if content.len() as u64 > self.max_response_size {
105→            bail!(
106→                "Response too large ({} bytes, max {} bytes) from {}",
107→                content.len(),
108→                self.max_response_size,
109→                url
110→            );
111→        }
112→
113→        Ok(FetchResponse {
114→            content,
115→            etag,
116→            last_modified,
117→        })
118→    }
119→
120→    /// Fetch with conditional request (If-None-Match).
121→    ///
122→    /// Returns `None` if content unchanged (304 Not Modified).
123→    pub fn fetch_if_changed(&self, url: &str, etag: Option<&str>) -> Result<Option<FetchResponse>> {
124→        let mut request = self.client.get(url);
125→
126→        if let Some(etag) = etag {
127→            request = request.header("If-None-Match", etag);
128→        }
129→
130→        let response = request.send()?;
131→
132→        if response.status() == reqwest::StatusCode::NOT_MODIFIED {
133→            return Ok(None);
134→        }
135→
136→        if !response.status().is_success() {
137→            bail!("HTTP {} fetching {}", response.status(), url);
138→        }
139→
140→        // Check Content-Length if available
141→        if let Some(len) = response.content_length() {
142→            if len > self.max_response_size {
143→                bail!(
144→                    "Response too large ({} bytes, max {} bytes) from {}",
145→                    len,
146→                    self.max_response_size,
147→                    url
148→                );
149→            }
150→        }

